}
return [{ json: { ok: true, user_id: $json.id, email: $json.email || null } }];

// Input: verify step returned { ok, user_id, email }.
// The original webhook payload sits on the Webhook node; its binary is named 'file'.
const user_id = $json.user_id;

const binary = $('upload::POST /uploads/room-photo').item.binary || {};
// n8n webhook v2 stores multipart files as field0, field1... so check both 'file' and 'file0'
const file = binary.file || binary.file0 || Object.values(binary)[0] || null;
if (!file) {
  return [{ json: { _error: { status: 400, body: { error: 'missing_file', code: 'invalid_file' } } } }];
}

const mime = (file.mimeType || '').toLowerCase();
const allowed = { 'image/jpeg': 'jpg', 'image/jpg': 'jpg', 'image/png': 'png' };
const ext = allowed[mime];
if (!ext) {
  return [{ json: { _error: { status: 400, body: { error: 'unsupported_media_type', code: 'invalid_file_type' } } } }];
}

const sizeBytes = Buffer.byteLength(file.data, 'base64');
if (sizeBytes > 10 * 1024 * 1024) {
  return [{ json: { _error: { status: 413, body: { error: 'file_too_large', code: 'file_too_large' } } } }];
}

// pure-JS UUID (no require('crypto') — blocked by n8n task-runner sandbox)
const upload_id = Array.from({length: 32}, () => (Math.random() * 16 | 0).toString(16)).join('');
const path = `${user_id}/${upload_id}`;

return [{
  json: { user_id, upload_id, ext, mime, path, storage_path: `user-uploads/${path}` },
  binary: { file }
}];

// Build the public URL for the uploaded object.
const row         = $('upload::Validate + name').item.json;
const user_id     = row.user_id;
const upload_id   = row.upload_id;
const path        = row.path;
const preview_url = `https://uzghfpxboktnbcbbthns.supabase.co/storage/v1/object/public/user-uploads/${path}`;
return [{ json: { user_id, upload_id, preview_url, storage_path: `user-uploads/${path}`, mime: row.mime } }];

const status = $json.statusCode || $json.status || 200;
