const ctx    = $('commit::Validate body').item.json;
if (!parent) {
  return [{ json: { _error: { status: 404, body: { error: 'parent_not_found', code: 'not_found' } } } }];
}
if (!parent.output_image_path || !parent.input_image_path) {
  return [{ json: { _error: { status: 400, body: { error: 'parent_incomplete', code: 'invalid_state' } } } }];
}
// Walk up the chain to the root to recover the original upload. Commit should
// render from the original room photo, not from an intermediate edit output.
// parent.input_image_path on an edit points at the previous generation's output;
// on a draft it points at user-uploads/<uid>/<upload_id>. For commit we want
// to combine: the ORIGINAL upload + the latest parent output + reference images.
return [{ json: {
  ...ctx,
  parent,
  parent_input_url:  `https://uzghfpxboktnbcbbthns.supabase.co/storage/v1/object/public/${parent.input_image_path}`,
  parent_output_url: `https://uzghfpxboktnbcbbthns.supabase.co/storage/v1/object/public/${parent.output_image_path}`
} }];

